// 世界引擎 · 脚本入口
// 独立脚本（后台 iframe 运行）：在酒馆网页放可拖动常驻悬浮球，点击展开中央大弹窗世界引擎页面。
import { reloadOnChatChange } from '@util/script';
import { createPinia } from 'pinia';
import { createApp } from 'vue';
import { useWorldEngineStore } from './store';
import App from './ui/App.vue';
import 悬浮球样式 from './ui/floating-ball.scss?raw';
import 弹窗srcdoc from './ui/modal-srcdoc.html';
import { 主题样式 } from './ui/theme';
import { 注册世界书宏 } from './世界书宏';
import { 推进世界, 通知 } from './推进';
import { 检查自动推进, 生成摘要 } from './摘要';
// 脚本运行在 iframe 中，$ 已指向酒馆网页，但 window/document 仍是脚本 iframe 自身的。
// 拖拽与尺寸需基于酒馆网页：用 window.parent（同源可用）。
const $酒馆doc = $(window.parent.document);
const 酒馆win = window.parent;
const 单例键 = Symbol.for('black-monk.world-engine.singleton');
const 单例宿主 = window.parent;
// 悬浮球
let $悬浮球 = null;
// 弹窗挂载状态
let 弹窗App = null;
let $弹窗iframe = null;
let $弹窗框架 = null;
let $全局样式节点 = null; // 注入到弹窗 iframe head 的全局主题样式
let 组件样式文本 = null;
let 页面原Overflow = null;
let 页面原HtmlOverflow = null;
let 弹窗布局清理 = null;
// 世界书宏注册句柄：世界氛围、单条暗流、按名切片，以及仅在继承聊天生效的轮回记忆。
let 宏句柄 = null;
// 脚本级共享 pinia：后台事件监听器（MESSAGE_RECEIVED 自动摘要/推进）与弹窗 UI 共用同一实例，
// 保证任意时刻 useWorldEngineStore() 都有 active pinia 可用。
let pinia = null;
// 悬浮球尺寸：窄屏（手机）略小，少占触摸区；桌面端 52px。
const 球尺寸 = () => (视口宽() < 600 ? 44 : 52);
// 接近 int32 上限但留余量，确保悬浮球始终位于酒馆所有 UI 之上
const 球zIndex = 2147483600;
const 球位置 = { x: 0, y: 0 }; // left/top 定位
let 刚拖动 = false; // 抑制拖动结束后的 click
function 视口宽() {
    return 酒馆win.innerWidth || 1200;
}
function 视口高() {
    return 酒馆win.innerHeight || 800;
}
function 切换弹窗() {
    if (弹窗App)
        关闭弹窗();
    else
        打开弹窗();
}
function 锁定页面滚动() {
    if (页面原Overflow !== null)
        return;
    const doc = window.parent.document;
    const body = doc.body;
    页面原HtmlOverflow = doc.documentElement.style.overflow;
    页面原Overflow = body.style.overflow;
    doc.documentElement.style.overflow = 'hidden';
    body.style.overflow = 'hidden';
}
function 恢复页面滚动() {
    if (页面原Overflow === null)
        return;
    const doc = window.parent.document;
    doc.documentElement.style.overflow = 页面原HtmlOverflow ?? '';
    doc.body.style.overflow = 页面原Overflow;
    页面原HtmlOverflow = null;
    页面原Overflow = null;
}
function 获取组件样式文本() {
    if (组件样式文本 !== null)
        return 组件样式文本;
    组件样式文本 = Array.from(document.head.querySelectorAll('style'))
        .map(style => style.textContent || '')
        .filter(Boolean)
        .join('\n');
    return 组件样式文本;
}
// 拖拽期间注入到酒馆 body 的全局抑制层：禁选区、禁指针事件，杜绝文字选中/元素 hover 带来的卡顿
let $拖拽抑制 = null;
function 开启拖拽抑制() {
    if ($拖拽抑制)
        return;
    $拖拽抑制 = $('<style>')
        .attr('script_id', getScriptId())
        .text(`*{user-select:none!important;-webkit-user-select:none!important;cursor:grabbing!important;}`)
        .appendTo('head');
}
function 关闭拖拽抑制() {
    if ($拖拽抑制) {
        $拖拽抑制.remove();
        $拖拽抑制 = null;
    }
}
function 创建悬浮球() {
    if ($悬浮球)
        return;
    // 默认右下角
    const s = 球尺寸();
    球位置.x = 视口宽() - s - 24;
    球位置.y = 视口高() - s - 90;
    const $ball = $('<div>')
        .attr('script_id', getScriptId())
        .addClass('we-floating-ball')
        .html('<i class="fa-solid fa-eye"></i>')
        .css({
        position: 'fixed',
        left: '0',
        top: '0',
        transform: `translate3d(${球位置.x}px, ${球位置.y}px, 0)`,
        width: s + 'px',
        height: s + 'px',
        zIndex: 球zIndex,
        cursor: 'grab',
        userSelect: 'none',
        touchAction: 'none',
        willChange: 'transform',
    });
    $ball.appendTo('body');
    $悬浮球 = $ball;
    // click：若刚拖动过则吞掉，否则开关弹窗
    $ball.on('click', () => {
        if (刚拖动) {
            刚拖动 = false;
            return;
        }
        切换弹窗();
    });
    // 拖拽：Pointer Events 统一鼠标 + 触摸；GPU 加速 + rAF
    $ball.on('pointerdown', (e) => {
        if (e.button !== undefined && e.button !== 0)
            return; // 仅主键/触摸
        const startX = e.clientX;
        const startY = e.clientY;
        const origX = 球位置.x;
        const origY = 球位置.y;
        let 拖动 = false;
        let rafId = 0;
        let 目标X = origX;
        let 目标Y = origY;
        const ballEl = $ball[0];
        // 拖拽中暂停脉冲动画，避免与 transform 更新竞争
        ballEl.style.animation = 'none';
        ballEl.style.cursor = 'grabbing';
        try {
            ballEl.setPointerCapture(e.pointerId);
        }
        catch {
            /* 跨 document 捕获可能失败，忽略 */
        }
        e.preventDefault();
        const apply = () => {
            球位置.x = 目标X;
            球位置.y = 目标Y;
            ballEl.style.transform = `translate3d(${目标X}px, ${目标Y}px, 0)`;
            rafId = 0;
        };
        const onMove = (ev) => {
            const dx = ev.clientX - startX;
            const dy = ev.clientY - startY;
            if (!拖动 && (Math.abs(dx) > 4 || Math.abs(dy) > 4)) {
                拖动 = true;
                开启拖拽抑制();
            }
            if (拖动) {
                目标X = Math.max(0, Math.min(视口宽() - 球尺寸(), origX + dx));
                目标Y = Math.max(0, Math.min(视口高() - 球尺寸(), origY + dy));
                if (!rafId)
                    rafId = requestAnimationFrame(apply);
                ev.preventDefault();
            }
        };
        const onUp = (ev) => {
            if (rafId) {
                cancelAnimationFrame(rafId);
                rafId = 0;
            }
            // 强制应用最后一帧目标，避免 rAF 被取消导致球停在倒数第二帧
            apply();
            $酒馆doc.off('pointermove', onMove);
            $酒馆doc.off('pointerup', onUp);
            $酒馆doc.off('pointercancel', onUp);
            关闭拖拽抑制();
            ballEl.style.animation = '';
            ballEl.style.cursor = 'grab';
            if (!拖动) {
                切换弹窗();
            }
            刚拖动 = true; // 抑制 pointerup 后浏览器补发的 click；拖动与轻点都需要吞掉一次
            酒馆win.setTimeout(() => {
                刚拖动 = false;
            }, 350);
            ev.preventDefault();
        };
        $酒馆doc.on('pointermove', onMove);
        $酒馆doc.on('pointerup', onUp);
        $酒馆doc.on('pointercancel', onUp);
    });
    // 视口缩放时把球拉回界内，避免消失在屏幕外
    酒馆win.addEventListener('resize', 视口校正, { passive: true });
}
function 视口校正() {
    if (!$悬浮球)
        return;
    const s = 球尺寸();
    球位置.x = Math.max(0, Math.min(视口宽() - s, 球位置.x));
    球位置.y = Math.max(0, Math.min(视口高() - s, 球位置.y));
    const el = $悬浮球[0];
    el.style.width = s + 'px';
    el.style.height = s + 'px';
    el.style.transform = `translate3d(${球位置.x}px, ${球位置.y}px, 0)`;
}
function 销毁悬浮球() {
    if ($悬浮球) {
        酒馆win.removeEventListener('resize', 视口校正);
        $悬浮球.remove();
        $悬浮球 = null;
    }
}
function 可视区域尺寸() {
    const visualViewport = 酒馆win.visualViewport;
    return {
        width: Math.floor(visualViewport?.width ?? 视口宽()),
        height: Math.floor(visualViewport?.height ?? 视口高()),
        left: Math.floor(visualViewport?.offsetLeft ?? 0),
        top: Math.floor(visualViewport?.offsetTop ?? 0),
    };
}
function 计算弹窗尺寸() {
    const viewport = 可视区域尺寸();
    const 移动端 = Math.min(viewport.width, 视口宽()) < 700 || viewport.height < 520;
    if (!移动端) {
        return {
            移动端,
            viewport,
            marginX: 0,
            marginY: 0,
            width: Math.min(900, Math.max(640, viewport.width - 80)),
            height: Math.min(640, Math.max(480, viewport.height - 80)),
        };
    }
    const marginX = viewport.width < 360 ? 8 : 10;
    const marginY = viewport.height < 520 ? 8 : 12;
    return {
        移动端,
        viewport,
        marginX,
        marginY,
        width: Math.max(260, viewport.width - marginX * 2),
        height: Math.max(280, viewport.height - marginY * 2),
    };
}
function 应用弹窗布局($mask, $frame, $iframe) {
    const layout = 计算弹窗尺寸();
    $mask.toggleClass('we-mask-mobile', layout.移动端).css({
        position: 'fixed',
        inset: layout.移动端 ? 'auto' : '0',
        left: layout.移动端 ? `${layout.viewport.left}px` : '0',
        top: layout.移动端 ? `${layout.viewport.top}px` : '0',
        width: layout.移动端 ? `${layout.viewport.width}px` : 'auto',
        height: layout.移动端 ? `${layout.viewport.height}px` : 'auto',
        zIndex: 球zIndex + 1,
        background: layout.移动端 ? 'rgba(0,0,0,0.48)' : 'rgba(0,0,0,0.6)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: layout.移动端 ? `${layout.marginY}px ${layout.marginX}px` : '0',
        boxSizing: 'border-box',
        overflow: 'hidden',
        overscrollBehavior: 'contain',
        touchAction: 'manipulation',
        transform: layout.移动端 ? 'translateZ(0)' : 'none',
    });
    $frame.css({
        position: 'relative',
        display: 'flex',
        width: `${layout.width}px`,
        height: `${layout.height}px`,
        maxWidth: layout.移动端 ? '100%' : '94vw',
        maxHeight: layout.移动端 ? '100%' : '90vh',
        minWidth: '0',
        minHeight: '0',
        boxSizing: 'border-box',
        padding: layout.移动端 ? '2px' : '3px',
        border: layout.移动端 ? '1px solid rgba(221, 184, 118, 0.76)' : '1px solid rgba(168, 128, 74, 0.5)',
        borderRadius: layout.移动端 ? '10px' : '12px',
        boxShadow: layout.移动端
            ? '0 18px 48px rgba(0, 0, 0, 0.82), 0 0 0 1px rgba(232, 112, 106, 0.18)'
            : '0 24px 70px rgba(0, 0, 0, 0.85), 0 0 40px rgba(184, 69, 61, 0.18)',
        background: '#07090a',
        overflow: 'hidden',
        touchAction: 'auto',
    });
    $iframe.css({
        display: 'block',
        width: '100%',
        height: '100%',
        minWidth: '0',
        minHeight: '0',
        border: '0',
        borderRadius: layout.移动端 ? '8px' : '9px',
        background: '#07090a',
        overflow: 'hidden',
        touchAction: 'auto',
    });
}
function 监听弹窗布局($mask, $frame, $iframe) {
    const update = () => 应用弹窗布局($mask, $frame, $iframe);
    酒馆win.addEventListener('resize', update, { passive: true });
    酒馆win.addEventListener('orientationchange', update, { passive: true });
    酒馆win.visualViewport?.addEventListener('resize', update, { passive: true });
    酒馆win.visualViewport?.addEventListener('scroll', update, { passive: true });
    弹窗布局清理 = () => {
        酒馆win.removeEventListener('resize', update);
        酒馆win.removeEventListener('orientationchange', update);
        酒馆win.visualViewport?.removeEventListener('resize', update);
        酒馆win.visualViewport?.removeEventListener('scroll', update);
        弹窗布局清理 = null;
    };
}
function 打开弹窗() {
    if (弹窗App)
        return;
    锁定页面滚动();
    const $mask = $('<div>')
        .attr('script_id', getScriptId())
        .attr('data-prev-overflow', 页面原Overflow ?? '')
        .addClass('we-mask');
    $mask.on('click', (e) => {
        if (e.target === $mask[0])
            关闭弹窗();
    });
    // 弹窗 iframe（中央大弹窗）
    // 不使用 createScriptIdIframe：其 srcdoc 含 adjust_iframe_height.js，会把 iframe 高度
    // 改写为 body.scrollHeight，与本弹窗「固定 640px + 内部滚动」的布局形成循环依赖，导致页面塌缩。
    const $iframe = $('<iframe>').attr({
        script_id: getScriptId(),
        frameborder: 0,
        srcdoc: 弹窗srcdoc,
        title: '世界引擎',
    });
    const $frame = $('<div>').attr('script_id', getScriptId()).addClass('we-dialog-frame');
    应用弹窗布局($mask, $frame, $iframe);
    监听弹窗布局($mask, $frame, $iframe);
    $弹窗iframe = $iframe;
    $弹窗框架 = $frame;
    $frame.append($iframe);
    $mask.append($frame);
    // 先挂 load 监听再连入文档，避免 srcdoc 解析过快导致 load 在监听前触发（重开后白屏）
    $iframe.on('load', on弹窗加载);
    $mask.appendTo('body');
}
function on弹窗加载() {
    const $iframe = $弹窗iframe;
    if (!$iframe)
        return; // 已被关闭
    const doc = $iframe[0].contentDocument;
    if (!doc || !doc.head || !doc.body) {
        console.warn('[世界引擎] 弹窗 iframe 文档未就绪，跳过挂载');
        return;
    }
    if (弹窗App)
        弹窗App.unmount(); // 容错：避免重复挂载
    try {
        // 主题样式（:root 变量）优先注入，确保组件 var(--c-*) 有定义
        $全局样式节点 = $('<style>').text(主题样式).prependTo(doc.head);
        // 组件样式在脚本生命周期内不会变化，合并成单个 style，减少每次开窗的 DOM 创建与样式重算。
        const 组件样式 = 获取组件样式文本();
        if (组件样式)
            $('<style>').attr('data-world-engine-components', '').text(组件样式).appendTo(doc.head);
        const app = createApp(App, { onClose: () => 关闭弹窗() }).use(pinia ?? createPinia());
        app.mount(doc.querySelector('#we-app') ?? doc.body);
        弹窗App = app;
    }
    catch (e) {
        console.error('[世界引擎] 弹窗挂载失败', e);
        通知('世界引擎面板加载失败，请重试', 'error');
    }
}
function 关闭弹窗() {
    if (弹窗布局清理)
        弹窗布局清理();
    if (弹窗App) {
        弹窗App.unmount();
        弹窗App = null;
    }
    if ($全局样式节点) {
        $全局样式节点.remove();
        $全局样式节点 = null;
    }
    if ($弹窗iframe) {
        $弹窗iframe.closest('.we-mask').remove(); // 连遮罩一起移除
        $弹窗iframe = null;
    }
    $弹窗框架 = null;
    恢复页面滚动();
}
$(() => {
    console.info('[世界引擎] 脚本加载');
    // 后台自动摘要/推进监听器也使用 pinia store（useWorldEngineStore）。
    // 必须在脚本加载时就创建并激活 pinia，否则未打开过弹窗的聊天里
    // MESSAGE_RECEIVED 回调会因无 active Pinia 抛错，自动摘要与自动推进静默失效。
    pinia = createPinia();
    setActivePinia(pinia);
    // 热重载不会触发旧模块的 pagehide。先调用上一实例留下的清理器，再清扫更早版本的残留 DOM/监听。
    const 旧实例清理 = 单例宿主[单例键];
    if (typeof 旧实例清理 === 'function') {
        try {
            旧实例清理();
        }
        catch (error) {
            console.warn('[世界引擎] 旧实例清理失败，继续强制清扫', error);
        }
    }
    const scriptId = getScriptId();
    // 类名为世界引擎专用；不再依赖 script_id，确保早期热重载留下的不同 ID 实例也能被清除。
    const $残留遮罩 = $('.we-mask');
    if ($残留遮罩.length) {
        window.parent.document.documentElement.style.overflow = '';
        window.parent.document.body.style.overflow = $残留遮罩.last().attr('data-prev-overflow') ?? '';
        $残留遮罩.remove();
    }
    $('.we-floating-ball').remove();
    $('.we-world-engine-style').remove();
    $('head > div, head > style')
        .filter((_index, element) => element.textContent?.includes('.we-floating-ball') ?? false)
        .remove();
    eventClearEvent(tavern_events.MESSAGE_RECEIVED);
    eventClearEvent(tavern_events.CHAT_CHANGED);
    // 传送悬浮球样式到酒馆网页 head
    const $styleWrap = $('<div>').attr('script_id', scriptId).addClass('we-world-engine-style').appendTo('head');
    $('<style>').text(悬浮球样式).appendTo($styleWrap);
    创建悬浮球();
    // 注册世界书宏：世界氛围、单条压缩暗流、按名绿灯切片与轮回记忆。
    // 世界书条目用这些宏即可让主线 AI 感知世界演变，无需依赖 getvar 嵌套路径解析。
    宏句柄 = 注册世界书宏();
    // 监听主线消息：自动摘要与自动推进分别读取各自开关，互不绑定。
    const 消息监听 = eventOn(tavern_events.MESSAGE_RECEIVED, async () => {
        try {
            const store = useWorldEngineStore();
            store.refresh();
            const engine = store.data;
            await 生成摘要(engine);
            if (await 检查自动推进(engine)) {
                await 推进世界(true);
            }
        }
        catch (e) {
            console.error('[世界引擎] 消息事件处理失败', e);
        }
    });
    const 聊天切换监听 = reloadOnChatChange();
    let 已清理 = false;
    const 清理实例 = () => {
        if (已清理)
            return;
        已清理 = true;
        消息监听.stop();
        聊天切换监听.stop();
        关闭弹窗();
        销毁悬浮球();
        关闭拖拽抑制();
        if (宏句柄) {
            宏句柄.unregister();
            宏句柄 = null;
        }
        $styleWrap.remove();
        $(window).off('pagehide', 清理实例);
        if (单例宿主[单例键] === 清理实例)
            delete 单例宿主[单例键];
    };
    单例宿主[单例键] = 清理实例;
    $(window).on('pagehide', 清理实例);
});
