export interface 世界引擎宗门状态切片 {
  名称: string;
  阵营: string;
  个人: {
    身份: string;
    在籍状态: string;
    所属机构: string;
    职务: string;
    贡献: number;
    声望: number;
    权限: string[];
  };
  核心指标: Record<string, number>;
  成员总数: number;
  仓库灵石: Record<string, number>;
  财政: {
    本期收入折合下品: number;
    本期支出折合下品: number;
  };
  经营概况: {
    任务数: number;
    建设项目数: number;
    政策数: number;
    异常机构: string[];
    异常设施: string[];
  };
}

function record(value: unknown): Record<string, any> {
  return value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, any>) : {};
}

function text(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value : fallback;
}

function number(value: unknown): number {
  const result = Number(value);
  return Number.isFinite(result) ? result : 0;
}

function numericRecord(value: unknown): Record<string, number> {
  return Object.fromEntries(Object.entries(record(value)).map(([key, item]) => [key, number(item)]));
}

/** 为世界推演提取紧凑宗门经营上下文；不向模型暴露完整名册、流水和仓库物资。 */
export function buildSectStateSlice(name: string, archive: unknown): 世界引擎宗门状态切片 | null {
  const normalizedName = name.trim();
  if (!normalizedName || !archive || typeof archive !== 'object' || Array.isArray(archive)) return null;

  const data = record(archive);
  const personal = record(data.个人档案);
  const memberStats = record(data.成员统计);
  const warehouse = record(data.仓库);
  const finance = record(data.财政);
  const institutions = record(data.机构);
  const facilities = record(data.设施);

  return {
    名称: normalizedName,
    阵营: text(data.阵营, '未知'),
    个人: {
      身份: text(personal.身份, '散修'),
      在籍状态: text(personal.在籍状态, '未加入'),
      所属机构: text(personal.所属机构),
      职务: text(personal.职务),
      贡献: number(personal.贡献),
      声望: number(personal.声望),
      权限: Array.isArray(personal.权限) ? personal.权限.filter((item): item is string => typeof item === 'string') : [],
    },
    核心指标: numericRecord(data.核心指标),
    成员总数: Object.values(memberStats).reduce((sum, item) => sum + Math.max(0, number(record(item).人数)), 0),
    仓库灵石: numericRecord(record(warehouse.灵石)),
    财政: {
      本期收入折合下品: number(finance.本期收入折合下品),
      本期支出折合下品: number(finance.本期支出折合下品),
    },
    经营概况: {
      任务数: Object.keys(record(data.任务)).length,
      建设项目数: Object.keys(record(data.建设队列)).length,
      政策数: Object.keys(record(data.当前政策)).length,
      异常机构: Object.entries(institutions)
        .filter(([, item]) => text(record(item).状态, '正常') !== '正常')
        .map(([key]) => key),
      异常设施: Object.entries(facilities)
        .filter(([, item]) => text(record(item).状态, '正常') !== '正常' || number(record(item).受损程度) > 0)
        .map(([key]) => key),
    },
  };
}
